package org.brightstats.desktop;

import java.util.*;
import com.google.gson.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.geometry.Insets;
import javafx.stage.Window;
import org.brightstats.stats.*;
import org.brightstats.data.*;

final class ClusterDialog {
    private ClusterDialog(){}
    record Settings(int sourceColumn,String sourceName,boolean twoLevel,boolean completeCases,SemModel.Model marginalModel,TwoLevelSem.Specification specification,ClusterSem.Options options){Settings{if(sourceColumn<0||sourceName==null||sourceName.isBlank()||options==null||twoLevel&&specification==null||!twoLevel&&marginalModel==null)throw new IllegalArgumentException("Configure a bound cluster source column and model.");}SemModel.Model observedModel(){return twoLevel?specification.within():marginalModel;}}
    static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=StatisticalInput.object(value,Set.of("sourceColumn","sourceName","twoLevel","completeCases","marginalModel","specification","options"),"cluster studio settings",false);boolean two=StatisticalInput.bool(o,"twoLevel",false);return new Settings(StatisticalInput.integer(o,"sourceColumn",-1),StatisticalInput.text(o.get("sourceName")),two,StatisticalInput.bool(o,"completeCases",false),two?null:SemModelInput.model(o.get("marginalModel")),two?ClusterInput.specification(o.get("specification")):null,ClusterInput.options(o.get("options")));}
    static Optional<Settings> show(Window owner,List<String> sourceNames,List<String> numericNames,double[][] data,Settings previous,SemModel.Model diagram){return new Editor(owner,sourceNames,numericNames,data,previous,diagram).dialog.showAndWait();}
    private static final class Editor {
        final Dialog<Settings> dialog=new Dialog<>();final ComboBox<String> cluster=new ComboBox<>();final CheckBox two=new CheckBox("Fit separate within/between two-level SEM"),complete=new CheckBox("Explicitly exclude rows with missing selected values or missing cluster IDs"),correction=new CheckBox("CR1 finite-sample correction for marginal cluster inference");final TextField bootstrap=new TextField("0"),seed=new TextField("42"),confidence=new TextField("0.95");final TextArea marginal=new TextArea(),within=new TextArea(),between=new TextArea();final Label error=new Label();final ListView<String> selected=new ListView<>();final Gson gson=new GsonBuilder().serializeNulls().setPrettyPrinting().create();final List<String> names;final double[][] data;Settings result;
        Editor(Window owner,List<String> sourceNames,List<String> numericNames,double[][] data,Settings previous,SemModel.Model diagram){
            names=List.copyOf(numericNames);this.data=data;dialog.initOwner(owner);dialog.setTitle("Cluster and two-level studio");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);cluster.getItems().setAll(sourceNames);cluster.setAccessibleText("Original source cluster-ID column");cluster.setId("cluster-source");selected.getItems().setAll(names);selected.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);selected.setPrefHeight(130);selected.setAccessibleText("Observed numeric variables for model templates");correction.setSelected(true);
            if(previous!=null){if(previous.sourceColumn()<sourceNames.size()&&sourceNames.get(previous.sourceColumn()).equals(previous.sourceName()))cluster.getSelectionModel().select(previous.sourceColumn());two.setSelected(previous.twoLevel());complete.setSelected(previous.completeCases());correction.setSelected(previous.options().smallSampleCorrection());bootstrap.setText(Integer.toString(previous.options().bootstrapReplicates()));seed.setText(Long.toString(previous.options().seed()));confidence.setText(Double.toString(previous.options().estimator().confidence()));if(previous.marginalModel()!=null)marginal.setText(gson.toJson(previous.marginalModel()));if(previous.specification()!=null){within.setText(gson.toJson(previous.specification().within()));between.setText(gson.toJson(previous.specification().between()));}for(int index:previous.observedModel().observed())selected.getSelectionModel().select(names.indexOf(previous.observedModel().variables().get(index)));}else{cluster.getSelectionModel().selectFirst();for(int i=0;i<names.size();i++)if(!names.get(i).equals(cluster.getValue())){selected.getSelectionModel().select(i);break;}generate();}
            Button generate=new Button("Build mean/covariance templates from selected variables");generate.setOnAction(e->{try{generate();error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});Button useDiagram=new Button("Use current reflective SEM diagram at both levels");useDiagram.setDisable(diagram==null);useDiagram.setOnAction(e->{if(diagram==null)return;marginal.setText(gson.toJson(diagram));within.setText(gson.toJson(zeroMeans(diagram)));between.setText(gson.toJson(diagram));});
            Label note=new Label("Cluster IDs stay attached to original source rows. Marginal inference clusters case scores and resamples whole clusters. Two-level ML separately models within and between covariance, with all means at the between level; it currently requires complete continuous selected data. Review every template assumption and starting value.");note.setWrapText(true);note.setMaxWidth(800);VBox setup=new VBox(10,note,new Label("Cluster-ID source column"),cluster,two,complete,correction,new Label("Whole-cluster bootstrap replicates (0 or 20–2,000; marginal mode only)"),bootstrap,new Label("Seed"),seed,new Label("Interval confidence"),confidence,new Label("Template variables (exclude the cluster-ID column)"),selected,generate,useDiagram);setup.setPadding(new Insets(12));
            for(TextArea area:List.of(marginal,within,between)){area.setPrefRowCount(18);area.setPrefColumnCount(72);}TabPane tabs=new TabPane(new Tab("Study setup",new ScrollPane(setup)),new Tab("Marginal RAM",marginal),new Tab("Within RAM (zero means)",within),new Tab("Between RAM and means",between));tabs.getTabs().forEach(t->t.setClosable(false));error.setWrapText(true);error.setId("cluster-error");VBox content=new VBox(10,tabs,error);content.setPadding(new Insets(12));content.setPrefSize(850,670);VBox.setVgrow(tabs,Priority.ALWAYS);dialog.getDialogPane().setContent(content);
            dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{int index=cluster.getSelectionModel().getSelectedIndex();if(index<0)throw new IllegalArgumentException("Select a cluster-ID source column.");int repeats=Integer.parseInt(bootstrap.getText().strip());if(two.isSelected()&&repeats!=0)throw new IllegalArgumentException("Whole-cluster bootstrap is currently available in marginal mode; set repeats to zero for two-level ML.");var options=new ClusterSem.Options(new FimlSem.Options(1500,1e-8,1e-12,Double.parseDouble(confidence.getText().strip())),correction.isSelected(),repeats,Long.parseLong(seed.getText().strip()));SemModel.Model model=two.isSelected()?null:SemModelInput.model(JsonParser.parseString(marginal.getText()));var specification=two.isSelected()?new TwoLevelSem.Specification(SemModelInput.model(JsonParser.parseString(within.getText())),SemModelInput.model(JsonParser.parseString(between.getText()))):null;result=new Settings(index,cluster.getValue(),two.isSelected(),complete.isSelected(),model,specification,options);SemDialog.columns(result.observedModel(),names);}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
        }
        void generate(){List<Integer> columns=new ArrayList<>(selected.getSelectionModel().getSelectedIndices());columns.removeIf(i->names.get(i).equals(cluster.getValue()));if(columns.isEmpty()||columns.size()>16)throw new IllegalArgumentException("Select 1–16 observed numeric variables separate from the cluster ID.");var model=template(names,data,columns,true,1);marginal.setText(gson.toJson(model));within.setText(gson.toJson(template(names,data,columns,false,.7)));between.setText(gson.toJson(template(names,data,columns,true,.3)));}
    }
    static SemModel.Model zeroMeans(SemModel.Model model){return new SemModel.Model(model.variables(),model.observed(),model.directed(),model.covariance(),new double[model.variables().size()],model.parameters().stream().filter(p->p.locations().stream().noneMatch(l->l.kind()==SemModel.Kind.INTERCEPT)).toList());}
    static SemModel.Model template(List<String> names,double[][] data,List<Integer> columns,boolean mean,double varianceFraction){int p=columns.size();double[][] covariance=new double[p][p];List<SemModel.Parameter> parameters=new ArrayList<>();double[] means=new double[p];for(int j=0;j<p;j++){int column=columns.get(j),count=0;double m=0,ss=0;for(var row:data)if(Double.isFinite(row[column])){count++;double delta=row[column]-m;m+=delta/count;ss+=delta*(row[column]-m);}if(count<3||!(ss>0))throw new IllegalArgumentException("Template variables need three finite values and positive variance.");double variance=ss/count;covariance[j][j]=variance*varianceFraction;means[j]=m;parameters.add(new SemModel.Parameter("Variance: "+names.get(column),List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,j,j)),covariance[j][j],variance,variance*1e-7,null));for(int k=0;k<j;k++)parameters.add(new SemModel.Parameter("Covariance: "+names.get(columns.get(k))+" / "+names.get(column),List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,j,k)),0,Math.sqrt(variance*covariance[k][k]/varianceFraction)));if(mean)parameters.add(new SemModel.Parameter("Mean: "+names.get(column),List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,j,0)),m,Math.sqrt(variance)));}return new SemModel.Model(columns.stream().map(names::get).toList(),java.util.stream.IntStream.range(0,p).toArray(),new double[p][p],covariance,new double[p],parameters);}
    static Settings smoke(Window owner,List<String> sourceNames,List<String> names,double[][] data,Settings current){var editor=new Editor(owner,sourceNames,names,data,current,null);editor.dialog.show();editor.bootstrap.setText("1");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing())throw new AssertionError("Invalid cluster repeat count accepted");editor.bootstrap.setText(Integer.toString(current.options().bootstrapReplicates()));((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();return Objects.requireNonNull(editor.dialog.getResult(),"Valid cluster settings not returned");}
}
